package br.com.cineo;
import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import static br.com.cineo.MainActivity.*;
class CoverEditor {
 final MainActivity a;int showId;boolean banner;CoverEditor(MainActivity activity){a=activity;}
 void select(int id,boolean wide){showId=id;banner=wide;a.pick(30,"image/*");}
 boolean result(int req,int res,Intent intent){if(req!=30)return false;if(res!=Activity.RESULT_OK||intent==null||intent.getData()==null)return true;final int g=a.generation;a.busy=true;a.loading.setVisibility(View.VISIBLE);a.images.execute(()->{try{android.net.Uri uri=intent.getData();BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream in=a.getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,bounds);}if(bounds.outWidth<1)throw new IOException("Imagem inválida.");BitmapFactory.Options opt=new BitmapFactory.Options();opt.inSampleSize=1;while(bounds.outWidth/opt.inSampleSize>1800||bounds.outHeight/opt.inSampleSize>1800)opt.inSampleSize*=2;Bitmap source;try(InputStream in=a.getContentResolver().openInputStream(uri)){source=BitmapFactory.decodeStream(in,null,opt);}if(source==null)throw new IOException("Não foi possível abrir.");try(InputStream in=a.getContentResolver().openInputStream(uri)){android.media.ExifInterface exif=new android.media.ExifInterface(in);int orientation=exif.getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);Matrix m=new Matrix();if(orientation==3)m.postRotate(180);if(orientation==6)m.postRotate(90);if(orientation==8)m.postRotate(270);if(orientation==2)m.postScale(-1,1);if(orientation==4)m.postScale(1,-1);if(orientation==5){m.postRotate(90);m.postScale(-1,1);}if(orientation==7){m.postRotate(270);m.postScale(-1,1);}if(!m.isIdentity())source=Bitmap.createBitmap(source,0,0,source.getWidth(),source.getHeight(),m,true);}catch(IOException ignored){}Bitmap bitmap=source;a.runOnUiThread(()->{if(g!=a.generation)return;a.busy=false;a.loading.setVisibility(View.GONE);edit(bitmap);});}catch(Exception ex){a.runOnUiThread(()->{if(g!=a.generation)return;a.busy=false;a.loading.setVisibility(View.GONE);a.notice(ex.getMessage(),true);});}});return true;}
 void edit(Bitmap bitmap){Dialog dialog=new Dialog(a,android.R.style.Theme_Material_NoActionBar_Fullscreen);LinearLayout page=a.col();page.setBackgroundColor(BG);page.setPadding(a.dp(18),a.dp(24),a.dp(18),a.dp(18));a.title(page,banner?"Enquadre o banner":"Enquadre o cartaz",24);a.text(page,"Arraste a imagem e ajuste o zoom. A área clara é o recorte final.",13,MUTED);CropView crop=new CropView(bitmap,banner?16f/9:2f/3);page.addView(crop,new LinearLayout.LayoutParams(-1,0,1));SeekBar zoom=new SeekBar(a);zoom.setMax(200);page.addView(zoom);zoom.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int n,boolean user){crop.zoom=1+n/100f;crop.invalidate();}});a.button(page,"Prévia e salvar",RED,()->{Bitmap out=crop.export();preview(dialog,out);});a.button(page,"Cancelar",CARD,()->dialog.dismiss());dialog.setContentView(page);dialog.show();}
 void preview(Dialog editor,Bitmap bitmap){LinearLayout panel=a.col();panel.setPadding(a.dp(16),a.dp(12),a.dp(16),a.dp(12));ImageView preview=new ImageView(a);preview.setImageBitmap(bitmap);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);panel.addView(preview,new LinearLayout.LayoutParams(-1,a.dp(280)));a.text(panel,banner?"Banner horizontal · destaque e continuar assistindo":"Cartaz vertical · catálogo e página da série",13,MUTED);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Prévia no Cineo").setView(panel).setNegativeButton("Ajustar",null).setPositiveButton("Salvar imagem",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,86,out);if(out.size()>2097152){Toast.makeText(a,"Imagem excedeu 2 MB.",1).show();return;}dialog.dismiss();editor.dismiss();a.safe(()->a.complete.post("/show/"+showId+"/art",a.obj("kind",banner?"banner":"cover","image",android.util.Base64.encodeToString(out.toByteArray(),2)),r->{if(r.has("proposal_id"))new AlertDialog.Builder(a).setTitle("Alteração enviada para análise").setMessage(r.optString("message")).setPositiveButton("Entendi",(d,n)->a.loadDetail(showId,"mine")).show();else a.loadDetail(showId,"mine");}));}));dialog.show();}
 class CropView extends View {
  Bitmap source;float ratio,zoom=1,dx=0,dy=0,oldX,oldY;RectF rect=new RectF();Paint paint=new Paint(3);Matrix transform=new Matrix();
  CropView(Bitmap bitmap,float aspect){super(a);source=bitmap;ratio=aspect;}
  void layoutImage(){float w=getWidth()*.9f,h=w/ratio;if(h>getHeight()*.9f){h=getHeight()*.9f;w=h*ratio;}rect.set((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);float scale=Math.max(w/source.getWidth(),h/source.getHeight())*zoom;float maxX=(source.getWidth()*scale-w)/2,maxY=(source.getHeight()*scale-h)/2;dx=Math.max(-maxX,Math.min(maxX,dx));dy=Math.max(-maxY,Math.min(maxY,dy));transform.reset();transform.postScale(scale,scale);transform.postTranslate(rect.centerX()-source.getWidth()*scale/2+dx,rect.centerY()-source.getHeight()*scale/2+dy);}
  protected void onDraw(Canvas canvas){super.onDraw(canvas);layoutImage();canvas.drawColor(Color.BLACK);canvas.drawBitmap(source,transform,paint);paint.setColor(0xaa000000);canvas.drawRect(0,0,getWidth(),rect.top,paint);canvas.drawRect(0,rect.bottom,getWidth(),getHeight(),paint);canvas.drawRect(0,rect.top,rect.left,rect.bottom,paint);canvas.drawRect(rect.right,rect.top,getWidth(),rect.bottom,paint);paint.setColor(WHITE);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(a.dp(2));canvas.drawRect(rect,paint);paint.setStrokeWidth(a.dp(.5f));for(int i=1;i<3;i++){canvas.drawLine(rect.left+rect.width()*i/3,rect.top,rect.left+rect.width()*i/3,rect.bottom,paint);canvas.drawLine(rect.left,rect.top+rect.height()*i/3,rect.right,rect.top+rect.height()*i/3,paint);}paint.setStyle(Paint.Style.FILL);}
  public boolean onTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){oldX=e.getX();oldY=e.getY();return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){dx+=e.getX()-oldX;dy+=e.getY()-oldY;oldX=e.getX();oldY=e.getY();invalidate();return true;}return true;}
  Bitmap export(){layoutImage();int w=banner?1280:720,h=banner?720:1080;Bitmap result=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(result);canvas.scale(w/rect.width(),h/rect.height());canvas.translate(-rect.left,-rect.top);canvas.drawBitmap(source,transform,paint);return result;}
 }
}
